train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)
num_samples = len(train_loader.dataset)  # Get total number of samples in the dataset
if num_samples > BATCH_LIMIT:
    train_loader.dataset.data = train_loader.dataset.data[:BATCH_LIMIT]
